def sort_by_latency(events: list[dict]) -> list[dict]:
    """Sort events by latency_ms in ascending order."""
    return sorted(events, key=lambda x: x.get('latency_ms', 0))


def sort_by_shard(events: list[dict]) -> list[dict]:
    """Sort events by shard ID in ascending order."""
    return sorted(events, key=lambda x: x.get('shard', 0))


def sort_by_event_id(events: list[dict]) -> list[dict]:
    """Sort events by event ID in ascending order."""
    return sorted(events, key=lambda x: x.get('id', ''))


def filter_by_shard(events: list[dict], shard_id: int) -> list[dict]:
    """Filter events that belong to a specific shard."""
    return [e for e in events if e.get('shard') == shard_id]


def filter_by_state(events: list[dict], state: str) -> list[dict]:
    """Filter events by their state field."""
    return [e for e in events if e.get('state') == state]


def filter_high_latency(events: list[dict], threshold_ms: int) -> list[dict]:
    """Filter events with latency greater than the threshold."""
    return [e for e in events if e.get('latency_ms', 0) > threshold_ms]


def filter_low_latency(events: list[dict], threshold_ms: int) -> list[dict]:
    """Filter events with latency less than the threshold."""
    return [e for e in events if e.get('latency_ms', 0) < threshold_ms]


def sum_latency(events: list[dict]) -> int:
    """Calculate the total sum of latency_ms for all events."""
    return sum(e.get('latency_ms', 0) for e in events)


def average_latency(events: list[dict]) -> float:
    """Calculate the average latency_ms for all events."""
    if not events:
        return 0.0
    return sum_latency(events) / len(events)


def max_latency(events: list[dict]) -> int:
    """Find the maximum latency_ms among all events."""
    if not events:
        return 0
    return max(e.get('latency_ms', 0) for e in events)


